                wait(2)
                self:destroy_item("blessing")
            end
        elseif (object.zone_id == 23 and object.id == 32) then
            if globals.blessings == 2 then
                self.room:send("The ancient druid's eyes light up as he receives the blessing.")
                globals.blessings = 3
                wait(2)
