-- 
-- p3 mini boss death trigger 55599
-- 
-- Death trigger for random gem and armor drops
-- 
-- set a random number to determine if a drop will
-- happen.
-- 
-- Miniboss setup
-- 
local bonus = random(1, 100)
local will_drop = random(1, 100)
-- 4 pieces of armor per sub_phase in phase_3
local what_armor_drop = random(1, 4)
-- 11 classes questing in phase_3
local what_gem_drop = random(1, 11)
-- 
if will_drop <= 30 then
    -- drop nothing and bail
    return _return_value
end
if will_drop <= 70 then
    -- Normal non-bonus drops
    if bonus <= 50 then
        -- drop a gem from the previous wear pos set
        self.room:spawn_object(557, 14 + what_gem_drop)
    elseif bonus >= 51 and bonus <= 90 then
        -- We're in the Normal drops from current wear pos set
        -- drop a gem from the current wear pos set
        self.room:spawn_object(557, 25 + what_gem_drop)
    else
        -- We're in the BONUS ROUND!!
        -- drop a gem from the next wear pos set
        self.room:spawn_object(557, 36 + what_gem_drop)
    end
elseif will_drop >= 71 and will_drop <= 90 then
    -- Normal non-bonus drops
    if bonus <= 50 then
        -- 
        self.room:spawn_object(553, 71 + what_armor_drop)
    elseif bonus >= 51 and bonus <= 90 then
        -- We're in the Normal drops from current wear pos set
        -- drop armor from the current wear pos set
        self.room:spawn_object(553, 75 + what_armor_drop)
    else
        -- We're in the BONUS ROUND!!
        -- drop a piece of armor from next wear pos
        self.room:spawn_object(553, 79 + what_armor_drop)
    end
else
    -- Normal non-bonus drops
    if bonus <= 50 then
        -- drop armor and gem from previous wear pos
        self.room:spawn_object(557, 14 + what_gem_drop)
        self.room:spawn_object(553, 71 + what_armor_drop)
    elseif bonus >= 51 and bonus <= 90 then
        -- We're in the Normal drops from current wear pos set
        -- drop a gem and armor from the current wear pos set
        self.room:spawn_object(553, 75 + what_armor_drop)
        self.room:spawn_object(557, 25 + what_gem_drop)
    else
        -- We're in the BONUS ROUND!!
        -- drop armor and gem from next wear pos
        self.room:spawn_object(557, 36 + what_gem_drop)
        self.room:spawn_object(553, 79 + what_armor_drop)
    end
end
return _return_value$trig$, '582118dc93350c1dbb80952973602e15'),
  -- data/triggers/030/030_150_intercity_transport_questmasters_greet.lua
  (30, 150, $trig$-- Converted from DG Script #3150: Intercity transport questmasters greet
-- Original: MOB trigger, flags: GREET, probability: 100%
-- This is a greet trigger for the transportation assistants who
-- move newbies between cities.
-- switch on self.id
local myname = "elf"
if (self.zone_id == 300 and self.id == 75) or (self.zone_id == 30 and self.id == 151) then
    myname = "barbarian"
elseif (self.zone_id == 30 and self.id == 152) then
    myname = "dwarf"
elseif (self.zone_id == 300 and self.id == 74) then
    myname = "drow"
elseif (self.zone_id == 300 and self.id == 76) then
    myname = "human"
elseif (self.zone_id == 300 and self.id == 77) then
    myname = "orc"
elseif (self.zone_id == 30 and self.id == 150) then
    -- legacy: questmaster 3150 had no myname; bail before sending speech
    return true
end
if actor.level < 16 and actor.is_player and actor:get_quest_stage("intercity_transport") == 0 then
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Would you like a trip to a faraway city?'</>")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'If so, just ask me <b:white>Yes</><blue> and I'll tell you all about it.'</>")
end$trig$, '1a43e6455d4fbcf58cb17ce42af2eb5e'),
  -- data/triggers/030/030_151_intercity_transport_questmasters_talk.lua
  (30, 151, $trig$-- Converted from DG Script #3151: Intercity transport questmasters talk
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
if actor:get_quest_stage("intercity_transport") == 0 then
    actor:start_quest("intercity_transport")
end
-- switch on self.id
local myname = "elf"
local dest = "Mielikki"
if (self.zone_id == 30 and self.id == 151) or (self.zone_id == 300 and self.id == 75) then
    myname = "barbarian"
    dest = "Ickle"
elseif (self.zone_id == 30 and self.id == 152) then
    myname = "dwarf"
    dest = "Anduin"
elseif (self.zone_id == 300 and self.id == 74) then
    myname = "drow"
    dest = "Anduin"
elseif (self.zone_id == 300 and self.id == 76) then
    myname = "human"
    dest = "Mielikki"
elseif (self.zone_id == 300 and self.id == 77) then
    myname = "orc"
    dest = "Ogakh"
elseif (self.zone_id == 30 and self.id == 150) then
    -- legacy: questmaster 3150 had no myname/dest; bail before sending speech
    return true
end
wait(3)
if actor.level < 16 then
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'As long as you're under level 16, I can transport you to " .. tostring(dest) .. ".'</>")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Just ask me 'transport', and I'll send you.'</>")
else
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'I send people below level 16 to " .. tostring(dest) .. ".'</>")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Unfortunately, you are too powerful.'</>")
end$trig$, '9acf40776cb94fee73cb5ee9a127948c'),
  -- data/triggers/030/030_154_transport_agents_ask.lua
  (30, 154, $trig$-- Converted from DG Script #3154: Transport agents ask
-- Original: MOB trigger, flags: SPEECH_TO, probability: 100%
-- This is the ask trigger for intercity transport questmasters.
-- It allows level 1-15 people to get transport by asking to
-- Anduin, Ickle, or Mielikki.
-- Much of this trigger is a copy of 3152.
-- ******************
-- * GENERAL SETUP **
-- ******************
local minlevel = 1
local maxlevel = 15
-- switch on self.id
local myname = "elf"
local dest_room = 3016
local dsname = "Mielikki"
if (self.zone_id == 30 and self.id == 151) or (self.zone_id == 300 and self.id == 75) then
    -- barbarian, sends to Ickle
    myname = "barbarian"
    dest_room = 10046
    dsname = "Ickle"
elseif (self.zone_id == 30 and self.id == 152) then
    -- dwarf, sends to Anduin
    myname = "dwarf"
    dest_room = 6015
    dsname = "Anduin"
elseif (self.zone_id == 300 and self.id == 74) then
    myname = "drow"
    dest_room = 6015
    dsname = "Anduin"
elseif (self.zone_id == 300 and self.id == 76) then
    myname = "human"
    dest_room = 3016
    dsname = "Mielikki"
elseif (self.zone_id == 300 and self.id == 77) then
    myname = "orc"
    dest_room = 30115
    dsname = "Ogakh"
elseif (self.zone_id == 30 and self.id == 150) then
    -- legacy: questmaster 3150 had no agent record; bail
    return true
end
wait(4)
-- **************************
-- * Check for eligibility **
-- **************************
if actor.level > 99 then
    self:command("eyebrow " .. tostring(actor.name))
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'Just goto " .. tostring(dest_room) .. ".'")
    return _return_value
elseif minlevel > actor.level then
    self:command("shake")
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'You are not experienced enough to go to " .. tostring(dsname) .. ".'</>")
    return _return_value
elseif actor.level > maxlevel then
    self:command("eyebrow " .. tostring(actor.name))
    actor:send("<blue>The " .. tostring(myname) .. " tells you, 'You are too powerful for me to transport.'</>")
    return _return_value
end
-- **************************
-- * Set origination color **
-- **************************
-- The color says where they came from.
-- It is seen by anyone standing at the destination.
local dcolor
if self.room == 3016 then
    -- Mielikki - GREEN
    dcolor = "&2green&0"
elseif self.room == 6015 then
    -- Anduin - RED
    dcolor = "&1red&0"
elseif self.room == 30115 then
    -- Ogakh - GRAY
    dcolor = "&9&bgray&0"
else
    -- Ickle - BLUE
    dcolor = "&4blue&0"
end
-- **********************
-- * Perform transport **
-- **********************
self.room:send_except(actor, tostring(self.name) .. " nods briefly to " .. tostring(actor.name) .. ".")
actor:send(tostring(self.name) .. " nods briefly to you.")
wait(4)
self.room:send_except(actor, tostring(self.name) .. " makes a magical gesture at " .. tostring(actor.name) .. ".")
actor:send(tostring(self.name) .. " makes a magical gesture at you.")
self.room:send_except(actor, tostring(actor.name) .. " disappears in a cloud of gray smoke.")
actor:teleport(get_room(math.floor(dest_room / 100), dest_room % 100))
get_room(math.floor(dest_room / 100), dest_room % 100):at(function()
    self.room:send_except(actor, tostring(actor.name) .. " arrives in a cloud of " .. tostring(dcolor) .. " smoke.")
end)
-- actor looks around$trig$, '934358973fb78aab96308875e15d81ac'),
