local hellstage = actor:get_quest_stage("hell_trident")
-- switch on self.id
-- Black Priestess p2
local reward, phase, level, spell1, spell2, go
if (self.zone_id == 60 and self.id == 32) then
    reward = 39
    phase = 1
    level = 65
    spell1 = actor:get_has_completed("banish")
