        actor:send("Wait for this hand to end before dealing again!")
        return _return_value
    end
    actor:send("You deal the cards across the table.")
    self.room:send_except(actor, tostring(actor.name) .. " deals the cards, beginning a new round.")
    local card = 1
    while card <= 52 do
        card[card] = 0
        local rank = card - 13 * ((card - 1)/ 13)
        local suit = ((card - 1)/ 13) + 1
        if rank == 1 then
            rank = "Two"
        elseif rank == 2 then
            rank = "Three"
        elseif rank == 3 then
            rank = "Four"
        elseif rank == 4 then
            rank = "Five"
        elseif rank == 5 then
            rank = "Six"
        elseif rank == 6 then
            rank = "Seven"
        elseif rank == 7 then
            rank = "Eight"
        elseif rank == 8 then
            rank = "Nine"
        elseif rank == 9 then
            rank = "Ten"
        elseif rank == 10 then
            rank = "Jack"
        elseif rank == 11 then
            rank = "Queen"
        elseif rank == 12 then
            rank = "King"
        elseif rank == 13 then
            rank = "Ace"
        end
        if suit == 1 then
            suit = "Clubs"
        elseif suit == 2 then
            suit = "Diamonds"
        elseif suit == 3 then
            suit = "Spades"
        elseif suit == 4 then
            suit = "Hearts"
        end
        name[card] = rank% of %suit
        globals["name" .. card] = globals["name" .. card] or true
        card = card + 1
    end
    local count = 0
