    end
    paralysis_victim_3 = nil
end
if paralysis_victim_4 and ((paralysis_victim_4.room ~= self.room) or (paralysis_expire_4 <= now)) then
    -- Clear paralysis on expired victim
    if paralysis_victim_4.room == self.room then
